      if (dom.last === 0) d.push(T("ngày cuối tháng"));
      if (dom.last > 0) d.push(T("{n} ngày trước ngày cuối tháng", { n: dom.last }));
      dom.near.forEach(n => d.push(T("ngày làm việc gần ngày {n} nhất", { n })));
