      if (!runs.length) { out.push("> " + T("Không có lần chạy nào trong 30 năm tới."), ""); return; }
      out.push("| # | " + T("Giờ máy") + " | UTC |", "|---:|---|---|", ...runs.map((t, k) => "| " + (k + 1) + " | " + stamp(t) + " | " + utc(t) + " |"), "");
