      const args = {};
      for (const a of RecipeOps.OPS[s.op].args || []) {
        const v = s.args && s.args[a.k];
        args[a.k] = a.type === "check" ? v === true : a.type === "select" ? (a.options.includes(v) ? v : a.def) : typeof v === "string" ? v.slice(0, 2000) : a.def;
      }
