    const head = [...v.subarray(0, HEX_SHOW)].map(b => b.toString(16).padStart(2, "0"));
    const rows = [];
    for (let i = 0; i < head.length; i += 16) rows.push(i.toString(16).padStart(8, "0") + "  " + head.slice(i, i + 16).join(" "));
